/* =====================================================================
   dax-exercises.js — 150 exercícios da trilha de Power BI (50 por nível)
   ---------------------------------------------------------------------
   Tipos:
     measure → medida avaliada num visual de matriz (linhas + Total)
               v.rows = coluna das linhas (null = cartão)
               v.filters = filtros da página { 'Tabela[Coluna]': valor }
     column  → coluna calculada (avaliada linha a linha em `table`)
     table   → tabela calculada (comparada linha a linha, sem ordem)
   Campos: t tópico · n título · s cenário · g objetivo · q gabarito ·
   k funções obrigatórias · fmt formato · h dica · show colunas exibidas.
   ===================================================================== */
